import re, json
with open('/tmp/repo_commits.html') as f:
    html = f.read()
# Find embedded JSON data
matches = re.findall(r'<script type=\"application/json\"[^>]*>(.*?)</script>', html, re.DOTALL)
for i, m in enumerate(matches):
    try:
        d = json.loads(m)
        if isinstance(d, dict):
            if 'payload' in d:
                print('Found payload', i)
    except:
        pass

# Try to find dates in the text
dates = re.findall(r'[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z', html)
if dates:
    print('Dates found:', sorted(dates, reverse=True)[:5])
"

